/** Immutable two-dimensional point: rotations (yaw, pitch) and screen coordinates. Every operation returns a new instance. */
interface Pos2D {
    /** The X coordinate. @since 0.2.0 @mc * */
    x: number;
    /** The Y coordinate. @since 0.2.0 @mc * */
    y: number;
    /** Adds another point. @since 0.2.0 @mc * */
    add(other: Pos2D): Pos2D;
    /** Component-wise lexicographic compare (x first, then y). @since 0.2.0 */
    compare(other: Pos2D): number;
    /** Multiplies component-wise by another point. @since 0.2.0 @mc * */
    mul(other: Pos2D): Pos2D;
    /** Scales by a factor. @since 0.2.0 @mc * */
    scale(factor: number): Pos2D;
    /** Subtracts another point. @since 0.2.0 @mc * */
    sub(other: Pos2D): Pos2D;
    /** JSON form so JSON.stringify renders the point directly. @since 0.3.0 @mc * */
    toJSON(): string;
}

/** Immutable three-dimensional point and direction: every operation returns a new instance. The script-facing workhorse for positions, directions, and offsets; JSON.stringify renders it as {"x":…,"y":…,"z":…}. */
interface Pos3D {
    /** The X coordinate. @since 0.1.0 @mc * */
    x: number;
    /** The Y coordinate. @since 0.1.0 @mc * */
    y: number;
    /** The Z coordinate. @since 0.1.0 @mc * */
    z: number;
    /** Adds another point or vector. @since 0.2.0 @mc * */
    add(other: Pos3D): Pos3D;
    /** The cross product. @since 0.1.0 @mc * */
    cross(other: Pos3D): Pos3D;
    /** The squared distance to another point. @since 0.2.0 @mc * */
    distanceSq(other: Pos3D): number;
    /** The distance to another point. @since 0.1.0 @mc * */
    distanceTo(other: Pos3D): number;
    /** Divides component-wise by another vector. @since 0.2.0 @mc * */
    div(other: Pos3D): Pos3D;
    /** The dot product. @since 0.1.0 @mc * */
    dot(other: Pos3D): number;
    /** Floors the coordinates onto the block grid. @since 0.1.0 @mc * */
    floor(): BlockPos;
    /** The vector length. @since 0.1.0 @mc * */
    length(): number;
    /** The squared vector length. @since 0.1.0 @mc * */
    lengthSq(): number;
    /** Linear interpolation toward another point by t (0..1). @since 0.1.0 @mc * */
    lerp(other: Pos3D, t: number): Pos3D;
    /** Multiplies component-wise by another vector. @since 0.2.0 @mc * */
    mul(other: Pos3D): Pos3D;
    /** The unit vector of the same direction (zero vector stays zero). @since 0.1.0 @mc * */
    normalize(): Pos3D;
    /** Scales by a factor. @since 0.2.0 @mc * */
    scale(factor: number): Pos3D;
    /** Subtracts another point or vector. @since 0.1.0 @mc * */
    sub(other: Pos3D): Pos3D;
    /** JSON form so JSON.stringify renders the point directly. @since 0.3.0 @mc * */
    toJSON(): string;
    /** Returns a copy with the X coordinate replaced. @since 0.1.0 @mc * */
    withX(value: number): Pos3D;
    /** Returns a copy with the Y coordinate replaced. @since 0.1.0 @mc * */
    withY(value: number): Pos3D;
    /** Returns a copy with the Z coordinate replaced. @since 0.1.0 @mc * */
    withZ(value: number): Pos3D;
}

