/** Handle of one event subscription; returned to scripts by events.on / once / onSync. Unsubscribing through the handle removes the subscription from dispatch; module dispose iterates its handles the same way. */
interface Subscription {
    /** Returns whether this subscription still receives events. @since 0.1.0 @mc * */
    readonly active: boolean;
    /** Returns whether this is a synchronous-channel subscription. @since 0.1.0 @mc * */
    readonly sync: boolean;
    /** Returns whether the pattern is a wildcard rather than an exact name. @since 0.1.0 @mc * */
    readonly wildcard: boolean;
    /** Subscription pattern: exact event name or wildcard (domain:*, *). @since 0.1.0 @mc * */
    pattern(): string;
    /** Unsubscribes; idempotent. @since 0.1.0 @mc * */
    unsubscribe(): void;
}

